(function(){
'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
document.title='About & sources · Version Compass';
document.documentElement.classList.add('perspective-enabled');
const css=document.createElement('link');css.rel='stylesheet';css.href='perspectives.css';document.head.append(css);
const styles=document.createElement('link');styles.rel='stylesheet';styles.href='about.css';document.head.append(styles);
const header=document.querySelector('.site-header');
new ResizeObserver(()=>document.documentElement.style.setProperty('--perspective-header-height',header.getBoundingClientRect().height+'px')).observe(header);
const data=window.VersionCompassSources;
document.querySelector('main').innerHTML=`
<div class="about-page">
<section aria-labelledby="about-title"><p class="eyebrow">PURPOSE & PROVENANCE</p><h1 id="about-title">About Version Compass</h1>
<p class="about-lead">Understand what changes, what it enables, and what to check before moving between Splunk releases, deployment models and Enterprise Security editions.</p>
<div class="about-columns"><div><h2>Built for decisions</h2><p>The Release Guide compares your current and target versions, highlights benefits and technical changes, and surfaces upgrade paths, compatibility gates and readiness checks. ES Editions compares documented capabilities and their prerequisites.</p><p>Cloud Environment narrows evidence by provider, region, compliance scope and experience. Perspectives prioritize relevant guidance without changing availability claims or hiding the complete comparison.</p></div>
<div><h2>Designed to stay traceable</h2><p>Shared links preserve selections. Print and PDF reports carry supporting evidence. Both visual themes use the same data. Version-specific guidance stays attached to its version; an older document is not automatically an inaccurate document.</p><p>Conflicting sources stay visible. Missing evidence means “not established,” not unavailable. This is independent planning guidance, not a substitute for vendor support, contractual entitlement or an authorization determination.</p></div></div>
</section>
<section aria-labelledby="automation-title"><h2 id="automation-title">Why automatic curation?</h2><p>Product releases, support policies and Cloud availability change on different schedules. Scheduled reviews reduce the gap between a published change and useful planning guidance, while preserving the evidence behind each update.</p>
<div class="about-columns"><div><h3>What gets checked</h3><p>Release notes, upgrade and compatibility documentation, edition matrices, Cloud service details and authorization evidence. Unambiguous supported changes update the shared datasets; ambiguous or contradictory claims stay qualified for review.</p></div><div><h3>When it runs</h3><ul><li>Release watch: daily, 5:00 a.m.</li><li>ES Editions: daily, 6:00 a.m.</li><li>Cloud and FedRAMP: daily, 7:00 a.m.</li><li>Guidance audit: Monday and Thursday, 8:00 a.m.</li></ul><p>All times Eastern. These are scheduled checks, not a live feed or a guarantee of completion. Material changes are documented in dated release notes; a new site publication does not mean every source was rechecked.</p></div></div></section>
<section aria-labelledby="sources-title"><h2 id="sources-title">Source compendium</h2><p>Every citation URL in the maintained product datasets and directly embedded official guidance, grouped once per URL. “Reviewed” shows a recorded source-level review, not a fresh verification today. “In use” means cited in maintained content, including historical releases.</p>
<details class="source-key"><summary>How to read dates and status</summary><p>Current as of is shown only as the recorded review date for that source’s cited scope. It is not a promise of present accuracy. Review date unknown means no source-level date was recorded. Out of date requires an explicit finding and date; age or removal alone does not establish inaccuracy.</p><p>Tracking began ${esc(data.trackingSince)}. First recorded is the register baseline, not the original adoption date. Earlier first-use dates remain “Not recorded” unless independently established. Retired sources remain here with their history. Historical records are not a reconstruction of citations removed before tracking began.</p></details>
<div class="source-filters"><label>Find a source<input id="source-search" type="search" placeholder="Title, URL or content location"></label><label>Used in<select id="source-area"><option value="">All areas</option>${[...new Set(data.sources.flatMap(r=>r.areas))].sort().map(x=>'<option>'+esc(x)+'</option>').join('')}</select></label><label>Usage<select id="source-usage"><option value="">All usage</option><option>In use</option><option>Retired</option></select></label><label>Review status<select id="source-status"><option value="">All statuses</option><option>Reviewed</option><option>Review date unknown</option><option>Needs reconciliation</option><option>Out of date</option></select></label><label>Sort<select id="source-sort"><option value="title">Title A–Z</option><option value="review-new">Review newest</option><option value="review-old">Review oldest</option><option value="first">First recorded</option><option value="status">Review status</option></select></label><button id="source-reset" type="button">Reset</button></div>
<p id="source-count" role="status" aria-live="polite"></p><div id="source-list"></div>
</section></div>`;
const ids=['search','area','usage','status','sort'],controls=Object.fromEntries(ids.map(k=>[k,document.getElementById('source-'+k)]));
function restore(){const p=new URLSearchParams(location.search);ids.forEach(k=>{controls[k].value=p.get('source_'+k)||(k==='sort'?'title':'');if(k!=='search'&&!controls[k].value)controls[k].value=k==='sort'?'title':'';});}
function render(sync=true){
 let rows=data.sources.filter(r=>(!controls.search.value||[r.title,r.url,...r.references].join(' ').toLowerCase().includes(controls.search.value.toLowerCase()))&&(!controls.area.value||r.areas.includes(controls.area.value))&&(!controls.usage.value||r.usage===controls.usage.value)&&(!controls.status.value||r.status===controls.status.value));
 const sort=controls.sort.value;rows.sort((a,b)=>{if(sort.startsWith('review')){if(!a.reviewed)return b.reviewed?1:0;if(!b.reviewed)return -1;return sort==='review-new'?b.reviewed.localeCompare(a.reviewed):a.reviewed.localeCompare(b.reviewed);}return (sort==='first'?a.firstRecorded:sort==='status'?a.status:a.title).localeCompare(sort==='first'?b.firstRecorded:sort==='status'?b.status:b.title)||a.url.localeCompare(b.url);});
 document.getElementById('source-count').textContent=rows.length+' of '+data.sources.length+' sources';
 document.getElementById('source-list').innerHTML=rows.length?rows.map(r=>`<article class="source-entry"><div class="source-heading"><h3><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)}</a></h3><span class="source-badge">${esc(r.usage)}</span><span class="source-badge">${esc(r.status)}</span></div><p class="source-url">${esc(r.url)}</p><p>${esc(r.areas.join(' · '))}</p><dl><div><dt>${r.outdatedAsOf?'Out of date as of':r.status==='Needs reconciliation'?'Last reviewed · disputed scope':'Current as of · recorded review'}</dt><dd>${esc(r.outdatedAsOf||r.reviewed||'Not established')}</dd></div><div><dt>First used</dt><dd>${esc(r.firstUsed||'Not recorded')}</dd></div><div><dt>First recorded</dt><dd>${esc(r.firstRecorded)}</dd></div><div><dt>Inaccuracy determined</dt><dd>${esc(r.outdatedAsOf||'No finding recorded')}</dd></div></dl>${r.reason?'<p>'+esc(r.reason)+'</p>':''}<details><summary>Usage locations & history</summary><ul>${r.references.map(p=>'<li>'+esc(p)+'</li>').join('')}</ul><ol>${r.events.map(e=>'<li>'+esc(e.date)+' · '+esc(e.event)+'</li>').join('')}</ol></details></article>`).join(''):'<p>No sources match these filters. Reset filters to see the complete register.</p>';
 if(sync){const u=new URL(location.href);ids.forEach(k=>{u.searchParams.delete('source_'+k);if(controls[k].value&&(k!=='sort'||controls[k].value!=='title'))u.searchParams.set('source_'+k,controls[k].value);});history.replaceState(null,'',u);}
}
ids.forEach(k=>controls[k].addEventListener(k==='search'?'input':'change',()=>render()));
document.getElementById('source-reset').addEventListener('click',()=>{ids.forEach(k=>controls[k].value=k==='sort'?'title':'');render();});
window.addEventListener('popstate',()=>{restore();render(false);});restore();render(false);
}());
